import heapq

def match(orders):
    trades = []
    book = {}  # id -> {'side','price','qty','time'}
    buy_heap = []  # (-price, time, id)
    sell_heap = []  # (price, time, id)
    time_counter = 0

    def clean_buy_heap():
        while buy_heap:
            negprice, t, oid = buy_heap[0]
            if oid in book and book[oid]['qty'] > 0 and book[oid]['side'] == 'buy':
                return
            heapq.heappop(buy_heap)

    def clean_sell_heap():
        while sell_heap:
            price, t, oid = sell_heap[0]
            if oid in book and book[oid]['qty'] > 0 and book[oid]['side'] == 'sell':
                return
            heapq.heappop(sell_heap)

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            continue

        oid = order[1]
        side = order[2]

        if typ == 'market':
            qty = order[3]
            price = None
        else:
            price = order[3]
            qty = order[4]

        this_time = time_counter
        time_counter += 1

        remaining = qty

        if side == 'buy':
            # match against sell_heap
            clean_sell_heap()
            while remaining > 0 and sell_heap:
                s_price, s_time, s_id = sell_heap[0]
                if s_id not in book or book[s_id]['qty'] <= 0 or book[s_id]['side'] != 'sell':
                    heapq.heappop(sell_heap)
                    clean_sell_heap()
                    continue
                if typ != 'market' and s_price > price:
                    break
                trade_qty = min(remaining, book[s_id]['qty'])
                trade_price = s_price
                trades.append([oid, s_id, trade_price, trade_qty])
                remaining -= trade_qty
                book[s_id]['qty'] -= trade_qty
                if book[s_id]['qty'] == 0:
                    del book[s_id]
                    heapq.heappop(sell_heap)
                clean_sell_heap()

            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'time': this_time}
                heapq.heappush(buy_heap, (-price, this_time, oid))

        else:  # side == 'sell'
            clean_buy_heap()
            while remaining > 0 and buy_heap:
                negprice, b_time, b_id = buy_heap[0]
                b_price = -negprice
                if b_id not in book or book[b_id]['qty'] <= 0 or book[b_id]['side'] != 'buy':
                    heapq.heappop(buy_heap)
                    clean_buy_heap()
                    continue
                if typ != 'market' and b_price < price:
                    break
                trade_qty = min(remaining, book[b_id]['qty'])
                trade_price = b_price
                trades.append([b_id, oid, trade_price, trade_qty])
                remaining -= trade_qty
                book[b_id]['qty'] -= trade_qty
                if book[b_id]['qty'] == 0:
                    del book[b_id]
                    heapq.heappop(buy_heap)
                clean_buy_heap()

            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'time': this_time}
                heapq.heappush(sell_heap, (price, this_time, oid))

    return trades

